import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/cookdinner/P09-%E9%94%85%E7%B1%BB%E5%BC%80%E9%94%85/01-%E7%85%8E%E9%A5%BC%E9%93%81%E7%9B%98.html","title":"01-煎饼铁盘开锅","lang":"zh-CN","frontmatter":{"title":"01-煎饼铁盘开锅","icon":"blog","date":"2025-07-24T10:55:38.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"1. 开锅 铸铁锅务必要开锅哦（珐琅锅请参考珐琅锅的开锅及保养），具体步骤如下： 先将锅内清洗干净，然后用火烤干，锅内没有水分后，转为小火。 倒入适量食用油，用筷子夹起一张纸巾，将纸巾蘸上部分食用油，将油均匀涂抹在锅内每个角落，持续 2-3 分钟，关火自然冷却。 冷却后重复开锅 2-3 次效果最佳。如有条件建议用猪皮完成上述步骤。等待锅子自然冷却，开锅...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"01-煎饼铁盘开锅\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-07-24T10:55:38.000Z\\",\\"dateModified\\":\\"2025-07-24T03:33:03.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/cookdinner/P09-%E9%94%85%E7%B1%BB%E5%BC%80%E9%94%85/01-%E7%85%8E%E9%A5%BC%E9%93%81%E7%9B%98.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"01-煎饼铁盘开锅"}],["meta",{"property":"og:description","content":"1. 开锅 铸铁锅务必要开锅哦（珐琅锅请参考珐琅锅的开锅及保养），具体步骤如下： 先将锅内清洗干净，然后用火烤干，锅内没有水分后，转为小火。 倒入适量食用油，用筷子夹起一张纸巾，将纸巾蘸上部分食用油，将油均匀涂抹在锅内每个角落，持续 2-3 分钟，关火自然冷却。 冷却后重复开锅 2-3 次效果最佳。如有条件建议用猪皮完成上述步骤。等待锅子自然冷却，开锅..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-07-24T03:33:03.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-07-24T10:55:38.000Z"}],["meta",{"property":"article:modified_time","content":"2025-07-24T03:33:03.000Z"}]]},"git":{"createdTime":1742454132000,"updatedTime":1753327983000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":7,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"efc03303438956ad1a5756ae39517759c646f862","time":1753327983000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加煎饼铁盘开锅文档并更新Python课程表"},{"hash":"abdd88761578e14be5e1ff409336d9f5a0e03100","time":1746871401000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"为所有食谱文档添加序号，更新标题格式"},{"hash":"174e9ca98296d3a4108bc7787dbf053ea2e45fc7","time":1746870050000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加芝麻香芋食谱文档，包含详细食材和步骤"},{"hash":"fcb3576514fa91c4259a1c6466f5ab986a2671eb","time":1744815374000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"{ text: \\"03-芝麻香芋\\", icon: \\"potato\\", link: \\"31-芝麻香芋\\" },"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"fb86babf5ceac5b6a218744c06d87db90bfa988a","time":1742454132000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文档，新增章节“RAG实战：基于ChatGLM3-6B+LangChain+Faiss搭建企业内部知识库”，并调整侧边栏以反映新内容"}]},"readingTime":{"minutes":1.83,"words":548},"filePathRelative":"column/cookdinner/P09-锅类开锅/01-煎饼铁盘.md","excerpt":"<h2>1. 开锅</h2>\\n<p>铸铁锅务必要开锅哦（珐琅锅请参考珐琅锅的开锅及保养），具体步骤如下：</p>\\n<ol>\\n<li>先将锅内清洗干净，然后用火烤干，锅内没有水分后，转为小火。</li>\\n<li>倒入适量食用油，用筷子夹起一张纸巾，将纸巾蘸上部分食用油，将油均匀涂抹在锅内每个角落，持续 2-3 分钟，关火自然冷却。</li>\\n<li>冷却后重复开锅 2-3 次效果最佳。如有条件建议用猪皮完成上述步骤。等待锅子自然冷却，开锅完成后，即可正常使用。</li>\\n</ol>\\n<h2>2. 养护</h2>\\n<p>使用后保养方法：</p>\\n<ol>\\n<li>\\n<p>烹饪完食物，温热水清洗；</p>\\n<blockquote>\\n<p>尽量不用洗洁精，洗洁精会把刚刚被锅吸收的油脂洗出来。</p>\\n</blockquote>\\n</li>\\n<li>\\n<p>在炉上烤干水汽，避免生锈；</p>\\n</li>\\n<li>\\n<p>锅烤干后在内壁涂上薄薄一层食用油小火加热烧下锅，使食用油沁入锅内进行养护</p>\\n<blockquote>\\n<p>这一步骤建议前期多进行几次，以后间隔时间可以长一些；</p>\\n</blockquote>\\n</li>\\n<li>\\n<p>关火、自然冷却，放置干燥处存放即可；</p>\\n</li>\\n</ol>","autoDesc":true}`),a={name:`01-煎饼铁盘.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="_1-开锅" tabindex="-1"><a class="header-anchor" href="#_1-开锅"><span>1. 开锅</span></a></h2><p>铸铁锅务必要开锅哦（珐琅锅请参考珐琅锅的开锅及保养），具体步骤如下：</p><ol><li>先将锅内清洗干净，然后用火烤干，锅内没有水分后，转为小火。</li><li>倒入适量食用油，用筷子夹起一张纸巾，将纸巾蘸上部分食用油，将油均匀涂抹在锅内每个角落，持续 2-3 分钟，关火自然冷却。</li><li>冷却后重复开锅 2-3 次效果最佳。如有条件建议用猪皮完成上述步骤。等待锅子自然冷却，开锅完成后，即可正常使用。</li></ol><h2 id="_2-养护" tabindex="-1"><a class="header-anchor" href="#_2-养护"><span>2. 养护</span></a></h2><p>使用后保养方法：</p><ol><li><p>烹饪完食物，温热水清洗；</p><blockquote><p>尽量不用洗洁精，洗洁精会把刚刚被锅吸收的油脂洗出来。</p></blockquote></li><li><p>在炉上烤干水汽，避免生锈；</p></li><li><p>锅烤干后在内壁涂上薄薄一层食用油小火加热烧下锅，使食用油沁入锅内进行养护</p><blockquote><p>这一步骤建议前期多进行几次，以后间隔时间可以长一些；</p></blockquote></li><li><p>关火、自然冷却，放置干燥处存放即可；</p></li></ol><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,9)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};